<script setup lang="ts">import {ElMessage} from 'element-plus';import {ref,reactive,onMounted} from 'vue'; import {useRouter} from 'vue-router'; import AppLayout from '../layouts/AppLayout.vue'; import {api} from '../api/client'; const rows=ref<any[]>([]),total=ref(0),dialog=ref(false),router=useRouter(); const form=reactive<any>({name:'',english_name:'',country:'',city:'',website:'',industry:'',customer_types:['Importer'],status:'potential',grade:'B',source:'',language:'English',timezone:'',business_scope:''}); async function load(){const r=await api.get('/customers',{params:{size:100}});rows.value=r.data.data;total.value=r.data.total} async function save(){await api.post('/customers',form);dialog.value=false;Object.assign(form,{name:'',english_name:'',country:'',city:'',website:'',industry:'',customer_types:['Importer'],status:'potential',grade:'B',source:'',language:'English',timezone:'',business_scope:''});await load();ElMessage.success('客户已创建')} onMounted(load);</script>
<template><AppLayout><div class="toolbar"><div><h2 style="margin:0">客户360°</h2><span class="muted">共 {{total}} 个客户</span></div><el-button type="primary" @click="dialog=true">新增客户</el-button></div><div class="card"><el-table :data="rows" @row-dblclick="r=>router.push(`/customers/${r.id}`)"><el-table-column prop="name" label="客户名称" min-width="220"/><el-table-column prop="country" label="国家"/><el-table-column prop="industry" label="行业"/><el-table-column label="属性"><template #default="s"><el-tag v-for="x in s.row.customer_types" :key="x" size="small" style="margin-right:4px">{{x}}</el-tag></template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="grade" label="等级" width="70"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" @click="router.push(`/customers/${s.row.id}`)">详情</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" title="新增客户" width="720"><el-form label-position="top"><div class="grid" style="grid-template-columns:1fr 1fr"><el-form-item label="客户名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="英文名称"><el-input v-model="form.english_name"/></el-form-item><el-form-item label="国家"><el-input v-model="form.country"/></el-form-item><el-form-item label="城市"><el-input v-model="form.city"/></el-form-item><el-form-item label="官网"><el-input v-model="form.website"/></el-form-item><el-form-item label="行业"><el-input v-model="form.industry"/></el-form-item><el-form-item label="客户属性"><el-select v-model="form.customer_types" multiple allow-create filterable style="width:100%"><el-option v-for="x in ['Importer','Distributor','Wholesaler','Retailer','Brand','Agent','Manufacturer','End User','E-commerce']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="客户状态"><el-input v-model="form.status"/></el-form-item><el-form-item label="等级"><el-input v-model="form.grade"/></el-form-item><el-form-item label="来源"><el-input v-model="form.source"/></el-form-item></div><el-form-item label="主营业务"><el-input v-model="form.business_scope" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></AppLayout></template>
